mapper.select:
SELECT COUNT(*) FROM RESERVATION r LEFT JOIN ASSET a ON a.ASSET_ID = r.ASSET_ID WHERE 1 = 1
AND a.CATEGORY = #{category}
AND r.STATUS = #{status}
AND TRUNC(r.START_TIME) = TO_DATE(#{startDate}, 'YYYY-MM-DD')

SELECT *
FROM (
SELECT r.*,
ROW_NUMBER() OVER (ORDER BY r.CREATED_AT DESC, r.RESERVATION_ID DESC) rn
FROM RESERVATION r
LEFT JOIN ASSET a ON a.ASSET_ID = r.ASSET_ID
WHERE 1 = 1

    AND a.CATEGORY = #{category}


    AND r.STATUS = #{status}


    AND TRUNC(r.START_TIME) = TO_DATE(#{startDate}, 'YYYY-MM-DD')

)
WHERE rn BETWEEN #{startRow} AND #{endRow}

mapper.update:
UPDATE RESERVATION
SET STATUS = 'APPROVED'
WHERE RESERVATION_ID = #{id}

mapper.select:
SELECT REJECT_REASON
FROM RESERVATION
WHERE RESERVATION_ID = #{id}
